    href: "/orders",
    icon: PackageSearch,
    cta: "Xem đơn hàng",
  },
  {
    title: "Cập nhật thông tin đại lý",
    desc: "Nếu cần điều chỉnh thông tin liên hệ hoặc người nhận, liên hệ bộ phận CSKH để được cập nhật nhanh.",
    href: "/support",
    icon: UserRoundCheck,
    cta: "Liên hệ hỗ trợ",
  },
];

export default function HelpPage() {
  return (
    <Page>
      <PageContent className={STORE_PAGE_CONTENT_CLASS}>
        <section>
          <Container max={STORE_CONTAINER_MAX_DEFAULT} className={`${STORE_CONTAINER_INSET} space-y-6`}>
      <div className="space-y-2">
        <h1 className="text-3xl sm:text-4xl font-bold text-foreground tracking-tight flex items-center gap-3">
          <CircleHelp className="w-8 h-8 text-primary shrink-0" aria-hidden />
          Trung tâm trợ giúp
        </h1>
        <p className="text-muted-foreground text-lg">
          Hướng dẫn nhanh để đại lý thao tác đúng flow trên Hub B2B.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {quickHelp.map((item) => (
          <Card key={item.title} className="rounded-2xl border-outline-variant">
            <CardHeader>
              <CardTitle className="text-xl font-black leading-tight flex items-start gap-2">
                <item.icon className="w-5 h-5 text-primary mt-1 shrink-0" />
                <span>{item.title}</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <p className="text-muted-foreground min-h-20">{item.desc}</p>
              <Link href={item.href} className="block w-full">
                <Button variant="outline" className="rounded-xl w-full">
                  {item.cta}
                </Button>
              </Link>
            </CardContent>
          </Card>
        ))}
      </div>
          </Container>
        </section>
      </PageContent>
    </Page>
  );
}

