            </div>

            {productsLoading ? (
              <Grid cols={4} gap={8}>
                {Array.from({ length: 4 }).map((_, i) => (
                  <div key={i} className="h-[520px] rounded-3xl bg-muted/40 animate-pulse" />
                ))}
              </Grid>
            ) : flashSale.length === 0 ? (
              <div className="text-center py-12 bg-muted/20 border border-dashed border-outline-variant rounded-2xl">
