  closeCart: () => void;
};

const CartDrawerContext = createContext<CartDrawerContextValue | null>(null);

export function useOpenCartDrawer(): () => void {
  const ctx = useContext(CartDrawerContext);
  if (!ctx) {
    throw new Error("useOpenCartDrawer must be used within CartDrawerHost");
  }
  return ctx.openCart;
}

function CartDrawerPanel({
  onNavigate,
  drawerOpen,
}: {
  onNavigate: () => void;
  drawerOpen: boolean;
}) {
  const {
    lines,
    unitCount,
    subtotal,
    promoDiscount,
    grandTotal,
    setQuantity,
    remove,
    clear,
  } = useCart();
  const isEmpty = lines.length === 0;
  const productIds = useMemo(
    () => [...new Set(lines.map((l) => l.productId))],
    [lines],
  );
  const {
    data: stockProducts,
    refetch: refetchStock,
    isFetching: isRefreshingStock,
  } = useCartStockProducts(productIds);
  useCartStockSync(stockProducts);

  useEffect(() => {
    if (!drawerOpen || !productIds.length) return;
    void refetchStock();
  }, [drawerOpen, productIds, refetchStock]);

  const stockIssues = useMemo(
    () =>
      stockProducts?.length
        ? cartStore.validateStockAgainstProducts(stockProducts)
        : [],
    [stockProducts],
  );
  const stockPending = cartNeedsStockSync(lines) && isRefreshingStock;
  const canCheckout =
    !isEmpty &&
    !stockPending &&
    stockIssues.length === 0 &&
    lines.every((l) => l.quantity > 0 && l.stock > 0);

  const handleCheckoutClick = (
    event: { preventDefault: () => void },
  ): void => {
    if (canCheckout) return;
    event.preventDefault();
    if (stockPending) {
      toast.message("Đang kiểm tra tồn kho…");
      return;
    }
    toast.error(stockIssues[0] ?? "Giỏ hàng chưa hợp lệ — vui lòng điều chỉnh số lượng");
  };
  const productSellTotals = useMemo(() => {
    const map = new Map<number, number>();
    for (const line of lines) {
      map.set(
        line.productId,
        (map.get(line.productId) ?? 0) + line.quantity,
      );
    }
    return map;
  }, [lines]);

  const cartGiftRules = useMemo(
    () => lines.flatMap((line) => giftRulesForCartLine(line)),
    [lines],
  );
  const { data: giftCatalogMap } = useGiftProductCatalogMap(cartGiftRules);
  const giftHrefForRule = useCallback(
    (rule: { id: string }) => giftCatalogMap?.get(rule.id),
    [giftCatalogMap],
  );

  return (
    <DrawerContent className="flex h-full max-h-svh w-full max-w-md flex-col border-l border-outline-variant p-0 data-[vaul-drawer-direction=right]:w-full data-[vaul-drawer-direction=right]:max-w-md data-[vaul-drawer-direction=right]:sm:max-w-md">
      <DrawerHeader className="flex flex-row items-center justify-between space-y-0 border-b border-outline-variant px-6 py-5">
        <div>
          <DrawerTitle className="flex items-center gap-2 text-xl font-extrabold">
            <ShoppingCart className="size-5 text-primary" aria-hidden />
            Giỏ hàng
          </DrawerTitle>
          <DrawerDescription className="text-xs">
            {isEmpty
              ? "Chưa có sản phẩm nào"
              : `${lines.length} loại · ${unitCount} đơn vị`}
          </DrawerDescription>
        </div>
        {!isEmpty && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={clear}
            className="rounded-lg text-destructive hover:bg-destructive/10"
          >
            <X className="mr-1 size-4" aria-hidden />
            Xoá tất cả
          </Button>
        )}
      </DrawerHeader>

      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto px-6 py-4">
        {!isEmpty && (stockPending || stockIssues.length > 0) && (
          <div
            className={cn(
              "flex items-start gap-2 rounded-xl border px-3 py-2.5 text-xs leading-relaxed",
              stockIssues.length > 0
                ? "border-destructive/30 bg-destructive/5 text-destructive"
                : "border-outline-variant/40 bg-muted/30 text-muted-foreground",
            )}
          >
            {stockPending ? (
              <Loader2 className="mt-0.5 size-4 shrink-0 animate-spin" aria-hidden />
            ) : (
              <AlertTriangle className="mt-0.5 size-4 shrink-0" aria-hidden />
            )}
            <p>
              {stockPending
                ? "Đang đồng bộ tồn kho từ server…"
                : stockIssues[0]}
            </p>
          </div>
        )}

        {isEmpty && (
          <div className="space-y-3 py-16 text-center">
            <Package2 className="mx-auto size-16 text-outline-variant opacity-30" />
            <p className="text-base font-bold text-muted-foreground">
              Giỏ hàng trống
            </p>
            <p className="text-sm text-muted-foreground">
              Hãy chọn sản phẩm từ danh mục để bắt đầu mua sắm.
            </p>
            <Button
              nativeButton={false}
              render={<Link href="/catalog" onClick={onNavigate} />}
              className="mt-2 rounded-xl"
            >
              Xem danh mục
            </Button>
          </div>
        )}

        {lines.map((line) => {
          const maxQty =
            line.stock > 0 ? Math.max(0, Math.floor(line.stock)) : line.quantity;
          const listUnit = line.listUnitPrice ?? line.unitPrice;
          const unitNow = line.unitPrice;
          const showListStrike = listUnit > unitNow;
          const listLineTotal = listUnit * line.quantity;
          const saleLineTotal = unitNow * line.quantity;

          const retailUnit = Math.max(0, Math.floor(listUnit));
          const promoUnitRaw = line.promoUnitPrice;
          const promoUnitFloored =
            promoUnitRaw != null &&
            Number.isFinite(promoUnitRaw) &&
            Math.floor(promoUnitRaw) > 0
              ? Math.floor(promoUnitRaw)
              : null;
          const hasPromoTier =
            promoUnitFloored != null &&
            retailUnit > 0 &&
            promoUnitFloored < retailUnit;
          const discountPct =
            hasPromoTier && retailUnit > 0
              ? Math.round(
                  ((retailUnit - promoUnitFloored!) / retailUnit) * 100,
                )
              : 0;
          const minQ = Math.max(0, Math.floor(line.minPromoQty ?? 0));
          const needMoreForKm =
            minQ > 1 && line.quantity < minQ ? minQ - line.quantity : 0;

          const giftRules = giftRulesForCartLine(line);
          const productSellQty =
            productSellTotals.get(line.productId) ?? line.quantity;

          return (
            <div
              key={`${line.productId}:${line.unitType}`}
              className="flex gap-3 rounded-2xl border border-outline-variant bg-background p-3"
            >
              <div className="flex size-16 shrink-0 items-center justify-center overflow-hidden rounded-xl border border-outline-variant/40 bg-white">
                {line.image ? (
                  <img
                    src={line.image}
                    alt=""
                    className="h-full w-full rounded-xl object-cover"
                  />
                ) : (
                  <Package2 className="size-7 text-outline-variant" />
                )}
              </div>
              <div className="min-w-0 flex-grow">
                <p className="line-clamp-2 text-sm font-bold leading-snug">
                  {line.name}
                </p>
                <ProductUnitLabelBadge className="mt-1" variant="muted">
                  {line.unitLabel}
                </ProductUnitLabelBadge>

                <div className="mt-2 flex flex-wrap items-end gap-1.5 sm:gap-2">
                  {showListStrike && (
                    <p className="mb-0.5 text-sm font-semibold text-muted-foreground line-through">
                      {formatVND(listUnit)}
                    </p>
                  )}
                  <p className="text-lg font-black text-primary sm:text-xl">
                    {formatVND(unitNow)}
                  </p>
                  <p className="mb-0.5 text-xs text-muted-foreground sm:text-sm">
                    / {line.unitLabel}
                  </p>
                  {line.isWholesale ? (
                    <ProductCartPriceBadge
                      saleActive={showListStrike}
                      className="mb-0.5"
                    />
                  ) : null}
                </div>

                {hasPromoTier && (
                  <div
                    className={cn(
                      "mt-1.5 rounded-lg border px-2.5 py-1.5 text-[11px] leading-snug sm:text-xs",
                      minQ > 1
                        ? line.isWholesale
                          ? "border-emerald-500/35 bg-emerald-500/10 text-emerald-950 dark:text-emerald-100"
                          : "border-amber-500/35 bg-amber-500/10 text-amber-950 dark:text-amber-100"
                        : "border-outline-variant/50 bg-muted/50 text-muted-foreground",
                    )}
                  >
                    {minQ > 1 ? (
                      <>
                        <p className="font-medium text-foreground">
                          Điều kiện KM: từ{" "}
                          <span className="font-bold text-primary">
                            {minQ} {line.unitType}
                          </span>{" "}
                          trở lên
                          {discountPct > 0 ? (
                            <>
                              {" "}
                              — giảm ~{discountPct}% so với giá niêm yết
                            </>
                          ) : null}
                          .
                        </p>
                        <p
                          className={cn(
                            "mt-0.5",
                            line.isWholesale
                              ? "text-emerald-800 dark:text-emerald-300"
                              : "text-amber-900 dark:text-amber-200",
                          )}
                        >
                          {line.isWholesale
                            ? `Đang đủ: ${line.quantity} ${line.unitType} — áp giá KM (${formatVND(promoUnitFloored!)} / ${line.unitLabel}).`
                            : `Hiện ${line.quantity} ${line.unitType}; cần thêm ít nhất ${needMoreForKm} ${line.unitType} để áp giá KM (${formatVND(promoUnitFloored!)} / ${line.unitLabel}).`}
                        </p>
                      </>
                    ) : (
                      <p>
                        {discountPct > 0 ? (
                          <>
                            Giá KM áp dụng mọi số lượng (khoảng {discountPct}% so
                            với {formatVND(retailUnit)} / {line.unitLabel}).
                          </>
                        ) : (
                          <>
                            Giá KM áp dụng mọi số lượng —{" "}
                            {formatVND(promoUnitFloored!)} / {line.unitLabel}.
                          </>
                        )}
                      </p>
                    )}
                  </div>
                )}

                {giftRules.length > 0 ? (
                  <div className="mt-1.5 space-y-1.5">
                    {giftRules.map((rule) => {
                      const giftUnlocked = isCartGiftRuleUnlocked(
                        rule,
                        line,
                        productSellQty,
                      );
                      const minQty = rule.trigger.minQty ?? 0;
                      return (
                        <div
                          key={rule.id}
                          className={cn(
                            "rounded-lg border px-2.5 py-1.5 text-[11px] leading-snug sm:text-xs",
                            giftUnlocked
                              ? "border-success/30 bg-success/10 text-success"
                              : "border-warning/30 bg-warning/10 text-warning",
                          )}
                        >
                          <p className="flex items-center gap-1.5 font-semibold text-foreground">
                            <Gift className="size-3.5 shrink-0" aria-hidden />
                            {giftUnlocked
                              ? "Đã đủ điều kiện nhận quà"
                              : "Ưu đãi quà tặng"}
                          </p>
                          <p className="mt-0.5 text-foreground">
                            <CartGiftRuleText
                              rule={rule}
                              giftHref={giftHrefForRule(rule)}
                            >
                              .
                            </CartGiftRuleText>
                          </p>
                          {!giftUnlocked && minQty > 0 ? (
                            <p className="mt-0.5 text-[10px] opacity-90 sm:text-xs">
                              Cần thêm{" "}
                              <span className="font-bold">
                                {Math.max(0, minQty - line.quantity)}
                              </span>{" "}
                              {line.unitType} trong giỏ để đủ điều kiện quà.
                            </p>
                          ) : null}
                        </div>
                      );
                    })}
                  </div>
                ) : null}

                {line.stock > 0 ? (
                  <p className="mt-1 text-[10px] text-muted-foreground">
                    Tối đa{" "}
                    <span className="font-semibold text-foreground tabular-nums">
                      {line.stock}
                    </span>{" "}
                    {line.unitType} trong kho
                  </p>
                ) : null}

                <div className="mt-2 flex items-center justify-between gap-2">
                  <div className="flex h-8 items-center overflow-hidden rounded-lg border border-outline-variant bg-surface">
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 rounded-none"
                      onClick={() =>
                        setQuantity(
                          line.productId,
                          line.unitType,
                          line.quantity - 1,
                        )
                      }
                    >
                      <Minus className="size-3" />
                    </Button>
                    <span className="w-9 text-center text-sm font-bold">
                      {line.quantity}
                    </span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 rounded-none"
                      disabled={line.quantity >= maxQty}
                      onClick={() =>
                        setQuantity(
                          line.productId,
                          line.unitType,
                          line.quantity + 1,
                        )
                      }
                    >
                      <Plus className="size-3" />
                    </Button>
                  </div>
                  <div className="shrink-0 text-right">
                    {showListStrike && (
                      <p className="text-xs text-muted-foreground line-through tabular-nums">
                        {formatVND(listLineTotal)}
                      </p>
                    )}
                    <p className="text-sm font-black tabular-nums text-primary">
                      {formatVND(saleLineTotal)}
                    </p>
                  </div>
                </div>
              </div>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="size-8 shrink-0 text-destructive hover:bg-destructive/10"
                onClick={() => remove(line.productId, line.unitType)}
              >
                <Trash2 className="size-4" />
              </Button>
            </div>
          );
        })}
      </div>

      {!isEmpty && (
        <DrawerFooter className="flex-col gap-3 border-t border-outline-variant px-6 py-5 sm:flex-col">
          <div className="space-y-1.5 text-sm">
            <div className="flex justify-between text-muted-foreground">
              <span>Tạm tính</span>
              <span className="font-semibold tabular-nums text-foreground">
                {formatVND(subtotal)}
              </span>
            </div>
            {promoDiscount > 0 && (
              <div className="flex justify-between text-primary">
                <span>Mã khuyến mãi</span>
                <span className="font-semibold tabular-nums">
                  −{formatVND(promoDiscount)}
                </span>
              </div>
            )}
            <div className="flex justify-between border-t border-outline-variant/60 pt-2 text-base font-semibold">
              <span className="text-muted-foreground">Ước tính thanh toán</span>
              <span className="text-xl font-black tabular-nums text-primary">
                {formatVND(grandTotal)}
              </span>
            </div>
          </div>
          <p className="text-xs text-muted-foreground">
            Thanh toán khi nhận hàng (COD). Phí vận chuyển sẽ được tính khi xác
            nhận đơn.
          </p>
          <Button
            nativeButton={false}
            disabled={!canCheckout}
            render={
              <Link
                href="/checkout"
                onClick={(e) => {
                  handleCheckoutClick(e);
                  if (canCheckout) onNavigate();
                }}
              />
            }
            className="h-12 w-full rounded-xl font-bold"
          >
            {stockPending
              ? "Đang kiểm tra tồn…"
              : !canCheckout
                ? "Không đủ tồn kho"
                : "Tiến hành đặt hàng"}
          </Button>
          <Button
            nativeButton={false}
            variant="outline"
            render={<Link href="/cart" onClick={onNavigate} />}
            className="w-full rounded-xl"
          >
            Mở trang giỏ đầy đủ
          </Button>
        </DrawerFooter>
      )}
    </DrawerContent>
  );
}

/** Bọc toàn bộ storefront cần nút mở giỏ (vd. quanh `<Header />`). */
export function CartDrawerHost({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const openCart = useCallback(() => setOpen(true), []);
  const closeCart = useCallback(() => setOpen(false), []);
  const value = useMemo(
    () => ({ openCart, closeCart }),
    [openCart, closeCart],
  );

  return (
    <CartDrawerContext.Provider value={value}>
      <Drawer
        direction="right"
        open={open}
        onOpenChange={setOpen}
        shouldScaleBackground={false}
      >
        {children}
        <CartDrawerPanel onNavigate={closeCart} drawerOpen={open} />
      </Drawer>
    </CartDrawerContext.Provider>
  );
}

src/components/shared/cart-gift-rule-tex.content:
"use client";

import Link from "next/link";
import type { ReactNode } from "react";
import type { ProductGiftRule } from "@workspace/api-client";
import { describeCartGiftRuleParts } from "@/lib/cart-gift-rules";

type CartGiftRuleTextProps = {
  rule: ProductGiftRule;
  /** Link catalog khi SP quà còn trên kho; undefined = chỉ text. */
  giftHref?: string | null;
  className?: string;
  children?: ReactNode;
};

/** Mô tả rule quà — tên quà có thể bấm sang CTSP khi `giftHref` có giá trị. */
export function CartGiftRuleText({
  rule,
  giftHref,
  className,
  children,
}: CartGiftRuleTextProps) {
  const { conditionText, giftQty, giftName } = describeCartGiftRuleParts(rule);

  return (
    <span className={className}>
      {conditionText} — tặng {giftQty}{" "}
      {giftHref ? (
        <Link
          href={giftHref}
          className="font-semibold underline underline-offset-2 transition-colors hover:text-primary"
          onClick={(e) => e.stopPropagation()}
        >
          {giftName}
        </Link>
      ) : (
        giftName
      )}
      {children}
    </span>
  );
}

src/components/shared/cart-line-item.tsx.content:
"use client";

import { Button } from "@ui/components/button";
import { ProductUnitLabelBadge } from "@ui/components/product";
import { Minus, Package2, Plus, Trash2 } from "lucide-react";
import type { CartLine } from "@/hooks/use-cart";
import { formatVND } from "@/lib/format";
import {
  giftRulesForCartLine,
  isCartGiftRuleUnlocked,
} from "@/lib/cart-gift-rules";
import type { ProductGiftRule } from "@workspace/api-client";
import { CartGiftRuleText } from "@/components/shared/cart-gift-rule-text";

export function cartLineMaxQty(line: CartLine): number {
  return Math.max(0, Math.floor(line.stock));
}

type CartLineItemProps = {
  line: CartLine;
  onQuantityChange: (quantity: number) => void;
  onRemove: () => void;
  /** Link catalog cho tên quà khi SP quà còn trên kho. */
  giftHrefForRule?: (rule: ProductGiftRule) => string | undefined;
};

/** Một dòng giỏ — layout giống danh sách sản phẩm ở trang checkout (ảnh, badge đơn vị, stepper). */
export function CartLineItem({
  line,
  onQuantityChange,
  onRemove,
  giftHrefForRule,
}: CartLineItemProps) {
  const maxQty = cartLineMaxQty(line);
  const listUnit = line.listUnitPrice ?? line.unitPrice;
  const showListStrike = listUnit > line.unitPrice;
  const giftRules = giftRulesForCartLine(line);
  const productSellQty = line.quantity;

  return (
    <div className="flex flex-col items-center gap-6 p-6 transition-colors hover:bg-muted/5 sm:flex-row">
      <div className="flex h-24 w-24 shrink-0 items-center justify-center overflow-hidden rounded-2xl border border-outline-variant/50 bg-white p-2 shadow-sm">
        {line.image ? (
          <img
            src={line.image}
            alt={line.name}
            className="w-full h-full object-cover rounded-lg"
          />
        ) : (
          <Package2 className="h-10 w-10 text-outline-variant" />
        )}
      </div>
      <div className="min-w-0 flex-grow text-center sm:text-left">
        <ProductUnitLabelBadge className="mb-2 uppercase tracking-wide">
          {line.unitLabel}
          {line.isWholesale ? " · Khuyến mãi" : " · Ban đầu"}
        </ProductUnitLabelBadge>
        <h3 className="line-clamp-2 text-lg font-bold leading-tight">{line.name}</h3>
        <div className="mt-2 flex flex-wrap items-center justify-center gap-2 sm:justify-start sm:gap-3">
          {showListStrike && (
            <span className="text-sm text-muted-foreground line-through decoration-muted-foreground/80">
              {formatVND(listUnit)}
            </span>
          )}
          <span className="text-xl font-extrabold text-foreground">
            {formatVND(line.unitPrice)}
          </span>
          <span className="text-sm text-muted-foreground">
            × {line.quantity} {line.unitType}
          </span>
        </div>
        {giftRules.length > 0 ? (
          <ul className="mt-2 space-y-1">
            {giftRules.map((rule) => {
              const unlocked = isCartGiftRuleUnlocked(
                rule,
                line,
                productSellQty,
              );
              const minQty = rule.trigger.minQty ?? 0;
              return (
                <li
                  key={rule.id}
                  className={`text-xs font-medium ${
                    unlocked ? "text-success" : "text-warning"
                  }`}
                >
                  {unlocked ? "Đủ điều kiện quà: " : "Quà tặng: "}
                  <CartGiftRuleText
                    rule={rule}
                    giftHref={giftHrefForRule?.(rule)}
                  >
                    {!unlocked && minQty > 0
                      ? ` (cần thêm ${Math.max(0, minQty - line.quantity)} ${line.unitType})`
                      : null}
                    .
                  </CartGiftRuleText>
                </li>
              );
            })}
          </ul>
        ) : null}
      </div>
      <div className="flex items-center gap-4">
        <div className="flex h-12 items-center overflow-hidden rounded-2xl border border-outline-variant bg-surface shadow-sm">
          <Button
            variant="ghost"
            size="icon"
            className="h-12 w-12 rounded-none"
            onClick={() => onQuantityChange(line.quantity - 1)}
          >
            <Minus className="h-4 w-4" />
          </Button>
          <span className="w-12 text-center text-lg font-extrabold">
            {line.quantity}
          </span>
          <Button
            variant="ghost"
            size="icon"
            className="h-12 w-12 rounded-none"
            disabled={line.quantity >= maxQty}
            onClick={() =>
              onQuantityChange(
                maxQty > 0
                  ? Math.min(line.quantity + 1, maxQty)
                  : line.quantity,
              )
            }
          >
            <Plus className="h-4 w-4" />
          </Button>
        </div>
        <Button
          variant="ghost"
          className="h-12 w-12 shrink-0 rounded-2xl text-destructive hover:bg-destructive/10"
          onClick={onRemove}
          aria-label="Xoá sản phẩm"
        >
          <Trash2 className="h-5 w-5" />
        </Button>
      </div>
    </div>
  );
}

src/components/shared/cart-order-summary.content:
"use client";

import Link from "next/link";
import { useState, useEffect } from "react";
import { toast } from "sonner";
import { Button } from "@ui/components/button";
import { Input } from "@ui/components/input";
import { Label } from "@ui/components/label";
import { ArrowRight, Tag, TicketPercent } from "lucide-react";
import { useCart } from "@/hooks/use-cart";
import { formatVND } from "@/lib/format";
import { PROMO_CODE_EXAMPLES } from "@workspace/promo-codes";
import { cn } from "@ui/lib/utils";

type CartOrderSummaryProps = {
  /** Giỏ hàng: nút sang checkout. Thanh toán: chỉ bảng giá (nút đặt hàng ở card khác). */
  variant?: "cart-aside" | "checkout-total";
};

function PromoField({ className }: { className?: string }) {
  const {
    appliedPromoCode,
    applyPromo,
    clearPromo,
    subtotal,
    promoDiscount,
    promoLabel,
    promoError,
  } = useCart();
  const [draft, setDraft] = useState(appliedPromoCode ?? "");

  useEffect(() => {
    setDraft(appliedPromoCode ?? "");
  }, [appliedPromoCode]);

  const handleApply = (): void => {
    const r = applyPromo(draft);
    if (!r.ok) {
      toast.error(r.message);
      return;
    }
    toast.success(r.label);
    setDraft(r.normalizedCode);
  };

  const handleClear = (): void => {
    clearPromo();
    setDraft("");
    toast.message("Đã gỡ mã khuyến mãi");
  };

  return (
    <div className={cn("space-y-2", className)}>
      <Label
        htmlFor="cart-promo-code"
        className="flex items-center gap-2 text-xs font-bold uppercase tracking-wide text-muted-foreground"
      >
        <TicketPercent className="size-3.5 text-primary" />
        Mã khuyến mãi
      </Label>
      <div className="flex gap-2">
        <Input
          id="cart-promo-code"
          value={draft}
          onChange={(e) => setDraft(e.target.value.toUpperCase())}
          placeholder="VD: GIAM50K"
          className="h-11 flex-1 rounded-xl border-outline-variant font-mono text-sm uppercase"
          disabled={subtotal <= 0}
          autoComplete="off"
        />
        <Button
          type="button"
          variant="secondary"
          className="h-11 shrink-0 rounded-xl px-4 font-bold"
          disabled={subtotal <= 0 || !draft.trim()}
          onClick={handleApply}
        >
          Áp dụng
        </Button>
      </div>
      <p className="text-[11px] leading-relaxed text-muted-foreground">
        Mã toàn đơn do kho cấu hình (đồng bộ từ máy chủ). Ví dụ:{" "}
        {PROMO_CODE_EXAMPLES.join(" · ")}. Giá KM theo{" "}
        <strong>từng sản phẩm / đơn vị</strong> (SL tối thiểu) tự cập nhật khi đổi số
        lượng — khác với ô mã bên dưới.
      </p>
      {appliedPromoCode && promoDiscount > 0 && promoLabel && (
        <div className="flex items-center justify-between rounded-xl border border-success/25 bg-success/5 px-3 py-2 text-sm">
          <span className="flex items-center gap-2 font-semibold text-success">
            <Tag className="size-4" />
            {promoLabel}
          </span>
          <Button
            type="button"
            variant="destructive"
            size="sm"
            className={"rounded-xl"}
            onClick={handleClear}
          >
            Gỡ mã
          </Button>
        </div>
      )}
      {promoError && (
        <p className="text-xs font-medium text-destructive">{promoError}</p>
      )}
    </div>
  );
}

export function CartOrderSummary({ variant = "cart-aside" }: CartOrderSummaryProps) {
  const { unitCount, subtotal, wholesaleSavings, promoDiscount, grandTotal } =
    useCart();

  return (
    <div
      className={cn(
        "space-y-5 border border-outline-variant bg-background p-6 shadow-sm",
        variant === "cart-aside" && "sticky top-24 rounded-3xl",
        variant === "checkout-total" && "rounded-2xl border-dashed",
      )}
    >
      <div className="space-y-1 border-b border-outline-variant/60 pb-4">
        <h2 className="text-lg font-extrabold tracking-tight text-foreground">
          Tổng đơn hàng
        </h2>
        <p className="text-xs text-muted-foreground">
          {unitCount} đơn vị trong giỏ — giá theo bảng giá ban đầu / khuyến mãi từng dòng.
        </p>
      </div>

      <PromoField />

      <dl className="space-y-3 text-sm">
        <div className="flex justify-between gap-4">
          <dt className="text-muted-foreground">Tạm tính</dt>
          <dd className="text-right font-bold tabular-nums">{formatVND(subtotal)}</dd>
        </div>
        {promoDiscount > 0 && (
          <div className="flex justify-between gap-4 text-primary">
            <dt className="font-medium">Giảm thêm (mã KM)</dt>
            <dd className="text-right font-bold tabular-nums">
              −{formatVND(promoDiscount)}
            </dd>
          </div>
        )}
        <div className="flex justify-between gap-4">
          <dt className="text-muted-foreground">Phí vận chuyển</dt>
          <dd className="text-right text-xs text-muted-foreground">
            Tính khi xác nhận đơn
          </dd>
        </div>
      </dl>
      {wholesaleSavings > 0 && (
        <div className="rounded-xl border border-success/20 bg-success/5 px-3 py-2.5 text-xs leading-relaxed text-success">
          <strong>Tiết kiệm từ giá khuyến mãi:</strong> so với giá ban đầu cùng quy cách, tạm tính đã
          thấp hơn{" "}
          <span className="font-black tabular-nums">
            {formatVND(wholesaleSavings)}
          </span>
          . Khoản này <em>không</em> trừ thêm lần nữa — chỉ để đối chiếu.
        </div>
      )}

      <div className="rounded-2xl bg-primary/5 px-4 py-3 ring-1 ring-primary/15">
        <div className="flex items-baseline justify-between gap-2">
          <span className="text-sm font-extrabold text-foreground">Thành tiền</span>
          <span className="text-2xl font-black tabular-nums tracking-tight text-primary">
            {formatVND(grandTotal)}
          </span>
        </div>
        <p className="mt-1 text-[11px] leading-relaxed text-muted-foreground">
          Thanh toán COD khi nhận hàng. Số tiền cuối khớp với đơn hàng sau khi hệ
          thống xác nhận tồn kho và mã KM.
        </p>
      </div>

      {variant === "cart-aside" && (
        <Button
          nativeButton={false}
          render={<Link href="/checkout" />}
          className="h-12 w-full rounded-xl text-base font-bold"
        >
          Tiến hành đặt hàng
          <ArrowRight className="ml-1 size-4" />
        </Button>
      )}
    </div>
  );
}

/** Khối nhập mã + gợi ý — dùng trong card tổng thanh toán checkout. */
export function CheckoutPromoField() {
  return (
    <div className="rounded-2xl border border-outline-variant/50 bg-muted/20 p-4">
      <PromoField />
    </div>
  );
}

src/components/shared/cart-sync-bridge.t.content:
"use client";

import { useEffect, useMemo, useRef } from "react";
import { useCart, useCartStockSync } from "@/hooks/use-cart";
import { useCartStockProducts } from "@/hooks/queries";
import { useSession } from "@/hooks/use-session";
import {
  hydrateCartAfterLogin,
  resetCartHydration,
  schedulePushUserCart,
} from "@/lib/cart-sync";

/**
 * Đồng bộ giỏ:
 * - Tồn kho từ catalog (polling 10s)
 * - Giỏ server khi đã đăng nhập (hydrate + debounce push)
 */
export function CartSyncBridge(): null {
  const session = useSession();
  const { lines, appliedPromoCode } = useCart();
  const productIds = useMemo(
    () => [...new Set(lines.map((l) => l.productId))],
    [lines],
  );
  const { data: products } = useCartStockProducts(productIds);
  useCartStockSync(products);

  const userId = session?.id ?? null;
  const hydrating = useRef(false);

  useEffect(() => {
    if (!userId) {
      resetCartHydration();
      return;
    }
    let cancelled = false;
    void (async () => {
      if (hydrating.current) return;
      hydrating.current = true;
      try {
        await hydrateCartAfterLogin();
      } finally {
        if (!cancelled) hydrating.current = false;
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [userId]);

  useEffect(() => {
    if (!userId) return;
    schedulePushUserCart(800);
  }, [userId, lines, appliedPromoCode]);

  return null;
}

