"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { ArrowRight, Package2, ShoppingCart, Tag } from "lucide-react";
import { Badge } from "@ui/components/badge";
import { Button } from "@ui/components/button";
import {
  ProductDetailOrderRow,
  ProductDetailUnitPicker,
  formatProductVnd,
  hasUnitWholesalePromo,
} from "@ui/components/product";
import {
  cartReservedBase,
  clampSellQty,
  remainingUnitStock,
  unitStock,
} from "@workspace/api-client";
import type { Product, ProductUnitType } from "@/lib/api";
import { getProductUnits } from "@/lib/catalog-filters";
import { unitSellingAndListPrice } from "@workspace/api-client";
import { cartLineQuantity, useCart } from "@/hooks/use-cart";

export type CatalogProductCardProps = {
  product: Product;
  categoryLabel: string;
  onAddToCart: (product: Product, unit: ProductUnitType, qty: number) => void;
};

export function CatalogProductCard({
  product: p,
  categoryLabel,
  onAddToCart,
}: CatalogProductCardProps) {
  const cart = useCart();
  const units = useMemo(() => getProductUnits(p), [p]);
  const [selectedUnit, setSelectedUnit] = useState<ProductUnitType>(units[0]!);
  const [quantity, setQuantity] = useState(1);

  const qtyInCart = cartLineQuantity(cart.lines, p.id, selectedUnit.type);
  const reservedBase = cartReservedBase(cart.lines, p.id);
  const pricingQty = qtyInCart + quantity;

  const isWholesale = hasUnitWholesalePromo(selectedUnit);
  const unitStockCount = unitStock(selectedUnit, p);
  const availableQty = remainingUnitStock(selectedUnit, p, reservedBase);
  const { current: displayPrice, list: listPrice } = unitSellingAndListPrice(
    selectedUnit,
    pricingQty,
  );

  const maxQty = availableQty;
  const minPurchaseQty = availableQty > 0 ? 1 : 0;
  const outOfStock = availableQty <= 0;
  const stockWarning = availableQty > 0 && quantity > availableQty * 0.8;
  const stockStatus = outOfStock ? "out" : stockWarning ? "low" : "ok";

  useEffect(() => {
    setQuantity((current) => {
      if (availableQty <= 0) return 0;
      return Math.max(1, Math.min(current || 1, availableQty));
    });
  }, [availableQty, selectedUnit.type]);

  const primaryImage = p.images?.[0];
  const firstCoupon = p.coupons?.[0];
  const meta = [p.brand, p.origin].filter(Boolean).join(" · ");

  const unitOptions = useMemo(
    () =>
      units.map((unit) => {
        const inCartU = cartLineQuantity(cart.lines, p.id, unit.type);
        const previewQty = inCartU + quantity;
        const { current, list } = unitSellingAndListPrice(unit, previewQty);
        return {
          type: unit.type,
          label: unit.label,
          currentPriceLabel: formatProductVnd(current),
          listPriceLabel: list != null ? formatProductVnd(list) : null,
          hasPromo: hasUnitWholesalePromo(unit),
        };
      }),
    [units, quantity, cart.lines, p.id],
  );

  const handleUnitChange = (type: string) => {
    const next = units.find((unit) => unit.type === type);
    if (!next) return;
    setSelectedUnit(next);
    const nextReserved = cartReservedBase(cart.lines, p.id);
    const nextAvailable = remainingUnitStock(next, p, nextReserved);
    setQuantity(nextAvailable > 0 ? 1 : 0);
  };

  const clampQty = (value: number) =>
    clampSellQty(value, minPurchaseQty, availableQty);

  const promoHint =
    isWholesale &&
    selectedUnit.minWholesaleQty > 1 &&
    pricingQty < selectedUnit.minWholesaleQty ? (
      <p className="text-[11px] leading-snug text-muted-foreground">
        Giá KM từ {selectedUnit.minWholesaleQty} {selectedUnit.type}
        {qtyInCart > 0 ? (
          <>
            {" "}
            · Tổng xét giá{" "}
            <span className="font-semibold text-foreground">{pricingQty}</span>
          </>
        ) : null}
      </p>
    ) : null;

  return (
    <article className="group/card flex h-full flex-col overflow-hidden rounded-2xl border border-outline-variant/30 bg-card shadow-sm ring-1 ring-black/[0.03] transition-shadow hover:border-primary/20 hover:shadow-md dark:ring-white/[0.04]">
      <Link
        href={`/catalog/${p.id}`}
        className="relative block overflow-hidden bg-muted/15"
      >
        {primaryImage ? (
          <img
            src={primaryImage}
            alt={p.name}
            className="aspect-[5/4] max-h-48 w-full object-cover transition-transform duration-500 group-hover/card:scale-[1.02]"
          />
        ) : (
          <div className="flex aspect-[5/4] max-h-48 w-full items-center justify-center bg-muted/25">
            <Package2 className="size-10 text-outline-variant" aria-hidden />
          </div>
        )}

        {firstCoupon ? (
          <Badge
            variant="coupon"
            size="xs"
            shape="pill"
            className="absolute top-2.5 left-2.5 max-w-[70%] truncate shadow-sm"
          >
            <Tag aria-hidden />
            {firstCoupon}
          </Badge>
        ) : null}

        <span className="pointer-events-none absolute inset-x-0 bottom-2 flex justify-center opacity-0 transition-opacity group-hover/card:opacity-100">
          <Badge variant="overlay" size="sm" className="gap-1 shadow-md">
            Xem chi tiết
            <ArrowRight className="size-3.5" aria-hidden />
          </Badge>
        </span>
      </Link>

      <div className="flex flex-1 flex-col gap-3 p-4">
        <div className="space-y-1.5">
          <Badge variant="category" size="xs">
            {categoryLabel}
          </Badge>
          <Link href={`/catalog/${p.id}`}>
            <h3 className="line-clamp-2 min-h-[2.5rem] text-sm font-bold leading-snug transition-colors hover:text-primary">
              {p.name}
            </h3>
          </Link>
          {meta ? (
            <p className="line-clamp-1 text-xs font-medium text-muted-foreground">
              {meta}
            </p>
          ) : null}
        </div>

        <div className="mt-auto space-y-3">
          {units.length > 1 ? (
            <ProductDetailUnitPicker
              options={unitOptions}
              selectedType={selectedUnit.type}
              onSelect={handleUnitChange}
              showPrice={false}
              dense
              showLabel={false}
            />
          ) : null}

          <ProductDetailOrderRow
            stacked
            unitPrice={displayPrice}
            listPrice={listPrice}
            unitLabel={selectedUnit.label}
            hasWholesale={isWholesale}
            qty={quantity}
            unitType={selectedUnit.type}
            onQtyChange={(next) => setQuantity(clampQty(next))}
            minQty={minPurchaseQty}
            maxQty={maxQty}
            stockCount={unitStockCount}
            stockStatus={stockStatus}
            footer={
              <>
                {promoHint}
                <Button
                  type="button"
                  className="h-10 w-full rounded-xl text-sm font-bold"
                  onClick={() => {
                    if (outOfStock || quantity > availableQty) return;
                    onAddToCart(p, selectedUnit, quantity);
                  }}
                  disabled={outOfStock}
                >
                  <ShoppingCart className="mr-1.5 size-4" />
                  {outOfStock ? "Hết hàng" : "Thêm vào giỏ"}
                </Button>
              </>
            }
          />
        </div>
      </div>
    </article>
  );
}

src/components/shared/header.tsx.content:
"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useMemo, useState } from "react";
import {
  Store,
  ShoppingCart,
  Package,
  Headphones,
  Box,
  ShieldCheck,
  Bell,
  UserCircle,
  ChevronDown,
  LogOut,
  User,
  Menu,
} from "lucide-react";
import { CartCountBadge } from "@ui/components/product";
import { useCart, cartStore } from "@/hooks/use-cart";
import { resetCartHydration } from "@/lib/cart-sync";
import { ThemeToggle } from "@ui/components/theme-toggle";
import { TextSizeToggle } from "@ui/components/text-size-toggle";
import { Separator } from "@ui/components/separator";
import { Button } from "@ui/components/button";
import { Heading, Text } from "@ui/components/typography";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@ui/components/dropdown-menu";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@ui/components/sheet";
import { useSession } from "@/hooks/use-session";
import { useOpenCartDrawer } from "@/components/shared/cart-drawer";

export function Header() {
  const isDevelopment = process.env.NODE_ENV === "development";
  const pathname = usePathname();
  const router = useRouter();
  const session = useSession();
  const { itemCount } = useCart();
  const openCart = useOpenCartDrawer();
  const [mobileNavOpen, setMobileNavOpen] = useState(false);

  const nav = useMemo(() => {
    const items: { href: string; label: string; icon: typeof ShoppingCart }[] = [
      { href: "/catalog", label: "Danh mục sỉ", icon: ShoppingCart },
    ];
    if (session) {
      items.push({ href: "/orders", label: "Đơn hàng", icon: Package });
    }
    items.push({ href: "/support", label: "Hỗ trợ", icon: Headphones });
    if (isDevelopment) {
      items.push({ href: "/graph", label: "Sơ đồ hệ thống", icon: Box });
    }
    return items;
  }, [session, isDevelopment]);

  const profileHref = "/profile";

  const handleLogout = () => {
    resetCartHydration();
    localStorage.removeItem("storesync_session");
    cartStore.clear();
    window.dispatchEvent(new Event("storesync-session"));
    router.push("/login");
  };

  return (
    <header className="sticky top-0 z-50 w-full border-b border-outline-variant bg-surface/85 backdrop-blur-md shadow-level-1 supports-[backdrop-filter]:bg-surface/70">
      <div className="mx-auto flex h-16 max-w-full items-center gap-2 px-4 sm:px-6">
        {/* Brand */}
        <Link href="/" className="flex items-center gap-2 group min-w-0 shrink">
          <div className="bg-primary/10 p-1.5 rounded-lg transition-colors group-hover:bg-primary/20 shrink-0">
            <Store className="size-6 text-primary" />
          </div>
          <Heading as="span" size="title" className="text-primary tracking-tight truncate max-w-[9rem] sm:max-w-none">Hub B2B</Heading>
        </Link>

        <div className="ml-auto flex items-center gap-1 md:hidden">
          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={openCart}
            aria-label={`Giỏ hàng${itemCount > 0 ? `, ${itemCount} loại` : ""}`}
            className="relative inline-flex size-10 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-primary"
          >
            <ShoppingCart className="size-5" />
            <CartCountBadge
              count={itemCount}
              className="-right-0.5 -top-0.5 h-4 min-w-4 text-[9px]"
            />
          </Button>
          <Sheet open={mobileNavOpen} onOpenChange={setMobileNavOpen}>
            <SheetTrigger
              render={
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="text-muted-foreground shrink-0"
                  aria-label="Mở menu"
                />
              }
            >
              <Menu className="size-5" />
            </SheetTrigger>
            <SheetContent side="right" className="w-[min(100vw,20rem)]">
              <SheetHeader>
                <SheetTitle>Menu</SheetTitle>
              </SheetHeader>
              <nav className="flex flex-col gap-1 mt-6 px-2">
                {nav.map((item) => {
                  const Icon = item.icon;
                  const isActive =
                    pathname === item.href ||
                    (item.href !== "/" &&
                      pathname.startsWith(`${item.href}/`));
                  return (
                    <Link
                      key={item.href}
                      href={item.href}
                      onClick={() => setMobileNavOpen(false)}
                      className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition-colors ${isActive ? "bg-primary/10 text-primary" : "text-foreground hover:bg-muted"}`}
                    >
                      <Icon className="size-4 shrink-0 opacity-80" />
                      {item.label}
                    </Link>
                  );
                })}
                <div className="my-3 border-t border-border" />
                <div className="flex items-center justify-between gap-2 px-1 py-2">
                  <Text as="span" variant="label" className="text-muted-foreground text-xs">Giao diện</Text>
                  <div className="flex items-center gap-1">
                    <TextSizeToggle />
                    <ThemeToggle />
                  </div>
                </div>
              </nav>
            </SheetContent>
          </Sheet>
        </div>

        {/* Nav desktop */}
        <nav className="ml-auto hidden md:flex items-center gap-4">
          {nav.map((item) => {
            const isActive =
              pathname === item.href ||
              (item.href !== "/" && pathname.startsWith(`${item.href}/`));
            return (
              <Link
                key={item.href}
                href={item.href}
                className={
                  "relative flex items-center gap-1.5 px-1 py-1 transition-all duration-200 " +
                  (isActive
                    ? "text-primary font-semibold"
                    : "text-muted-foreground hover:text-primary")
                }
              >
                <Text as="span" variant="label" className="font-bold">{item.label}</Text>
                {isActive && (
                  <span className="absolute -bottom-[21px] left-0 right-0 h-0.5 bg-primary rounded-full" />
                )}
              </Link>
            );
          })}

          <Separator orientation="vertical" className="mx-2 h-6 bg-outline-variant/50" />

          <div className="flex items-center gap-1">
            <Button
              type="button"
              variant="ghost"
              size="icon"
              onClick={openCart}
              aria-label={
                itemCount > 0 ? `Giỏ hàng, ${itemCount} loại` : "Giỏ hàng"
              }
              className="relative inline-flex size-9 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-primary"
            >
              <ShoppingCart className="size-5" />
              <CartCountBadge
                count={itemCount}
                className="-right-1 -top-1 h-5 min-w-5 text-[10px]"
              />
            </Button>
            <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-primary">
              <Bell className="size-5" />
            </Button>
            {session ? (
              <DropdownMenu>
                <DropdownMenuTrigger
                  className="flex items-center gap-2 rounded-lg px-2 py-1.5 hover:bg-muted transition-colors"
                >
                  {session.role === "admin" ? (
                    <ShieldCheck className="size-5 text-primary" />
                  ) : (
                    <UserCircle className="size-5 text-primary" />
                  )}
                  <span className="text-xs font-semibold text-foreground max-w-28 truncate">
                    {session.displayName}
                  </span>
                  <ChevronDown className="size-3.5 text-muted-foreground" />
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-56">
                  <DropdownMenuGroup>
                    <DropdownMenuLabel>Tài khoản</DropdownMenuLabel>
                    <DropdownMenuItem onClick={() => router.push(profileHref)}>
                      <User className="size-4" />
                      Trang cá nhân
                    </DropdownMenuItem>
                  </DropdownMenuGroup>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem variant="destructive" onClick={handleLogout}>
                    <LogOut className="size-4" />
                    Đăng xuất
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <Link href="/login">
                <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-primary">
                  <UserCircle className="size-5" />
                </Button>
              </Link>
            )}
          </div>

          <Separator orientation="vertical" className="mx-2 h-6 bg-outline-variant/50" />

          <div className="flex items-center gap-2">
            <TextSizeToggle />
            <ThemeToggle />
          </div>
        </nav>
      </div>
    </header>
  );
}

src/components/shared/order-status-table.content:
import Link from "next/link";
import {
  ArrowRight,
  CircleCheckBig,
  OctagonX,
  Truck,
} from "lucide-react";
import { Card, CardContent } from "@ui/components/card";
import { Button } from "@ui/components/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@ui/components/table";
import { StoreOrderRowStatusBadge } from "@ui/components/product";

export type OrderStatusTableRow = {
  /** Khóa React (vd. id số đơn); hiển thị mã đơn ở cột đầu dùng `orderCode`. */
  rowKey: string;
  orderCode: string;
  date: string;
  statusText: string;
  etaOrTotal: string;
  status: "shipping" | "completed" | "cancelled";
  href: string;
  ctaLabel: string;
};

export function OrderStatusTable({ rows }: { rows: OrderStatusTableRow[] }) {
  return (
    <Card className="border-border py-0 overflow-hidden">
      <CardContent className="p-0 overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted/30">
              <TableHead className="pl-6">Mã đơn</TableHead>
              <TableHead>Ngày đặt</TableHead>
              <TableHead>Trạng thái</TableHead>
              <TableHead>Thông tin</TableHead>
              <TableHead className="text-right pr-6">Hành động</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.map((row) => (
              <TableRow key={row.rowKey}>
                <TableCell className="pl-6 font-bold">{row.orderCode}</TableCell>
                <TableCell className="text-muted-foreground">{row.date}</TableCell>
                <TableCell>
                  <StoreOrderRowStatusBadge
                    status={row.status}
                    icon={
                      row.status === "shipping"
                        ? Truck
                        : row.status === "completed"
                          ? CircleCheckBig
                          : OctagonX
                    }
                  >
                    {row.statusText}
                  </StoreOrderRowStatusBadge>
                </TableCell>
                <TableCell className="text-muted-foreground">{row.etaOrTotal}</TableCell>
                <TableCell className="text-right pr-6">
                  <Link href={row.href}>
                    <Button variant="outline" size="sm">
                      {row.ctaLabel}
                      <ArrowRight className="w-4 h-4 ml-1.5" />
                    </Button>
                  </Link>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

src/components/shared/product-card.tsx.content:
"use client";

import Link from "next/link";
import { ArrowRight, Plus, ShoppingCart, Tag } from "lucide-react";
import { Card, CardContent, CardFooter } from "@ui/components/card";
import { Badge } from "@ui/components/badge";
import { Button } from "@ui/components/button";
import { Heading, Text } from "@ui/components/typography";

type ProductCardVariant = "catalog" | "flash";

type ProductCardProps = {
  variant: ProductCardVariant;
  href: string;
  name: string;
  image: string;
  price: string;
  originalPrice?: string;
  category?: string;
  minQty?: string;
  coupon?: string;
  discountLabel?: string;
  soldText?: string;
  progressPercent?: number;
  topRightBadge?: string;
  primaryCtaLabel?: string;
  onAddToCart?: () => void;
};

export function ProductCard({
  variant,
  href,
  name,
  image,
  price,
  originalPrice,
  category,
  minQty,
  coupon,
  discountLabel,
  soldText,
  progressPercent,
  topRightBadge = "Chính hãng",
  primaryCtaLabel = "Xem chi tiết",
  onAddToCart,
}: ProductCardProps) {
  return (
    <Card className="py-0 border-outline-variant overflow-hidden group hover:shadow-xl transition-all duration-300 bg-background rounded-2xl">
      <Link href={href} className={`block relative ${variant === "catalog" ? "w-full h-64" : "h-64"} bg-gradient-to-b from-white to-muted/20`}>
        <div className="w-full h-full rounded-2xl bg-white/70 border border-outline-variant/30 shadow-inner flex items-center justify-center overflow-hidden">
          <img
            src={image}
            alt={name}
            className="w-full h-full rounded-3xl object-cover drop-shadow-[0_10px_20px_rgba(0,0,0,0.18)] rounded-lg transition-transform duration-500 group-hover:scale-105"
          />
        </div>

        <div className="absolute top-4 right-4">
          <Badge variant="overlay" size="sm" className="shadow-sm">
            {topRightBadge}
          </Badge>
        </div>

        {coupon && variant === "catalog" && (
          <div className="absolute top-4 left-4 bg-warning/20 text-warning-foreground px-3 py-1.5 rounded-xl font-bold text-sm border border-warning/30 flex items-center gap-1.5 shadow-sm backdrop-blur-sm">
            <Tag className="w-4 h-4" />
            {coupon}
          </div>
        )}

        {discountLabel && variant === "flash" && (
          <div className="absolute top-4 left-4 bg-destructive text-white px-3 py-1.5 rounded-xl font-black text-sm shadow-lg">
            {discountLabel}
          </div>
        )}
      </Link>

      <CardContent className={`p-6 flex flex-col ${variant === "catalog" ? "h-[260px]" : "h-[245px]"} space-y-4`}>
        {category && (
          <div className="text-sm font-bold text-primary/80 uppercase tracking-widest">{category}</div>
        )}

        <Link href={href} className="group/title">
          <Heading
            as="h3"
            size="title"
            className={`line-clamp-2 leading-tight group-hover/title:text-primary transition-colors ${variant === "catalog" ? "min-h-[4rem]" : "min-h-[3.5rem]"}`}
          >
            {name}
          </Heading>
        </Link>

        <div className="mt-auto pt-4 border-t border-outline-variant/30 space-y-2">
          <div className="flex flex-wrap items-baseline gap-2">
            {originalPrice && (
              <Text variant="muted" className="line-through font-medium text-sm shrink-0">
                {originalPrice}
              </Text>
            )}
            <Heading as="span" size="title" color="primary" className="shrink-0">
              {price}
            </Heading>
          </div>

          {variant === "catalog" && minQty && (
            <div className="text-base font-bold text-primary mt-1 flex items-center gap-1">
              <Plus className="w-4 h-4" />
              {minQty}
            </div>
          )}

          {variant === "flash" && soldText && (
            <div className="space-y-2">
              <div className="flex justify-between text-sm font-bold">
                <Text as="span" variant="muted">{soldText}</Text>
                <Text as="span" variant="body" className="text-primary font-bold">Hot 🔥</Text>
              </div>
              <div className="h-3 bg-muted rounded-full overflow-hidden border border-border/50 p-0.5">
                <div
                  className="h-full bg-gradient-to-r from-primary to-teal-500 rounded-full"
                  style={{ width: `${Math.max(0, Math.min(100, progressPercent ?? 0))}%` }}
                />
              </div>
            </div>
          )}
        </div>
      </CardContent>

      <CardFooter className={variant === "catalog" ? "" : undefined}>
        <div className={`w-full flex ${variant === "catalog" ? "items-center gap-2" : ""}`}>
          <Link href={href} className={variant === "catalog" ? "flex-1" : "w-full"}>
            <Button className="w-full h-14 rounded-2xl font-bold text-lg shadow-lg hover:bg-primary/90 transition-all flex gap-2">
              <ArrowRight className="size-5" />
              {primaryCtaLabel}
            </Button>
          </Link>
          {variant === "catalog" && onAddToCart && (
            <Button
              className="h-14 w-14 rounded-2xl shadow-lg hover:scale-110 transition-all hover:bg-primary/90"
              aria-label="Thêm vào giỏ"
              onClick={onAddToCart}
            >
              <ShoppingCart className="w-7 h-7" />
            </Button>
          )}
        </div>
      </CardFooter>
    </Card>
  );
}

src/components/shared/product-detail.tsx.content:
"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  ShoppingCart,
  Truck,
  AlertTriangle,
  CheckCircle2,
} from "lucide-react";
import { Button } from "@ui/components/button";
import { toast } from "sonner";
import {
  ProductDetailActions,
  ProductDetailCallout,
  ProductDetailGallery,
  ProductDetailInfoHeader,
  ProductDetailLayout,
  ProductDetailMetaGrid,
  ProductDetailOrderRow,
  ProductDetailPromoGiftsSection,
  hasUnitWholesalePromo,
  ProductDetailPurchaseCard,
  ProductDetailPurchaseCardSection,
  ProductDetailUnitPicker,
  formatProductVnd,
} from "@ui/components/product";
import type { Product, ProductUnitType } from "@/lib/api";
import { unitSellingAndListPrice } from "@workspace/api-client";
import { getProductUnits } from "@/lib/catalog-filters";
import {
  cartReservedBase,
  clampSellQty,
  productBaseStock,
  remainingUnitStock,
  unitStock,
} from "@workspace/api-client";
import { cartLineQuantity, useCart } from "@/hooks/use-cart";
import { useGiftProductCatalogMap } from "@/hooks/use-gift-product-catalog";
import { resolveGiftRulesForUnit } from "@workspace/api-client";
import { ProductSuggestions } from "@/components/shared/product-suggestions";

type ProductDetailProps = {
  product: Product;
  backHref?: string;
  supportHref?: string;
};

function resolveDisplayImages(unit: ProductUnitType, product: Product) {
  const own = (unit.images ?? []).filter((url) => url.trim().length > 0);
  if (own.length > 0) return own;
  return (product.images ?? []).filter((url) => url.trim().length > 0);
}

export function ProductDetail({
  product,
  backHref = "/catalog",
  supportHref = "/support",
}: ProductDetailProps) {
  const categoryLabel =
    product.category.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) ||
    product.category;
  const cart = useCart();
  const fallbackUnit: ProductUnitType = useMemo(
    () => ({
      type: product.unit,
      label: product.unit,
      wholesalePrice: product.wholesalePrice,
      retailPrice: product.retailPrice,
      minWholesaleQty: 1,
      qtyPerUnit: 1,
      images: product.images ?? undefined,
    }),
    [product],
  );
  const units: ProductUnitType[] = (() => {
    const parsed = getProductUnits(product);
    return parsed.length > 0 ? parsed : [fallbackUnit];
  })();

  const [selectedUnit, setSelectedUnit] = useState<ProductUnitType>(units[0]!);
  const displayImages = useMemo(
    () => resolveDisplayImages(selectedUnit, product),
    [selectedUnit, product],
  );

  const baseStock = productBaseStock(product);
  const reservedBase = cartReservedBase(cart.lines, product.id);
  const unitStockCount = unitStock(selectedUnit, product);
  const qtyInCart = cartLineQuantity(
    cart.lines,
    product.id,
    selectedUnit.type,
  );
  const availableQty = remainingUnitStock(
    selectedUnit,
    product,
    reservedBase,
  );
  const maxQty = availableQty;
  const minPurchaseQty = availableQty > 0 ? 1 : 0;
  const [qty, setQty] = useState(availableQty > 0 ? 1 : 0);

  useEffect(() => {
    setQty((current) => {
      if (availableQty <= 0) return 0;
      return Math.max(1, Math.min(current || 1, availableQty));
    });
  }, [availableQty, selectedUnit.type]);
  const pricingQty = qtyInCart + qty;
  const productSellQty = useMemo(() => {
    const fromCart = cart.lines
      .filter((line) => line.productId === product.id)
      .reduce((sum, line) => sum + line.quantity, 0);
    return fromCart + qty;
  }, [cart.lines, product.id, qty]);
  const giftRules = useMemo(
    () => resolveGiftRulesForUnit(selectedUnit, product.fulfillmentNote),
    [selectedUnit, product.fulfillmentNote],
  );
  const { data: giftCatalogMap } = useGiftProductCatalogMap(giftRules);
  const giftHrefForRule = useMemo(
    () => (rule: (typeof giftRules)[number]) => giftCatalogMap?.get(rule.id),
    [giftCatalogMap],
  );

  const isWholesale = hasUnitWholesalePromo(selectedUnit);
  const showPromoGiftsSection = isWholesale || giftRules.length > 0;
  const { current: unitPrice, list: listPrice } = unitSellingAndListPrice(
    selectedUnit,
    pricingQty,
  );

  const totalUnits = qty * Math.max(selectedUnit.qtyPerUnit, 1);
  const totalPrice = unitPrice * qty;
  const stockWarning = availableQty > 0 && qty > availableQty * 0.8;
  const outOfStock = availableQty <= 0;

  const clampQty = (value: number) =>
    clampSellQty(value, minPurchaseQty, availableQty);

  const handleUnitChange = (type: string) => {
    const next = units.find((unit) => unit.type === type);
    if (!next) return;
    setSelectedUnit(next);
    const nextReserved = cartReservedBase(cart.lines, product.id);
    const nextAvailable = remainingUnitStock(next, product, nextReserved);
    setQty(nextAvailable > 0 ? 1 : 0);
  };

  const handleAddToCart = () => {
    const safeQty = clampQty(qty);
    if (outOfStock || safeQty <= 0 || safeQty > availableQty) {
      if (!outOfStock && safeQty > availableQty) {
        toast.error(`Chỉ còn ${availableQty} ${selectedUnit.type} trong kho`);
        setQty(clampQty(safeQty));
      }
      return;
    }
    const result = cart.add(product, selectedUnit, safeQty);
    if (!result.ok) {
      toast.error(
        result.reason === "out_of_stock"
          ? `Chỉ còn ${availableQty} ${selectedUnit.type} trong kho`
          : "Số lượng không hợp lệ",
      );
      return;
    }
    toast.success(
      `Đã thêm ${result.added} ${selectedUnit.label} vào giỏ hàng`,
      {
        description: `${product.name} · Tổng: ${formatProductVnd(unitPrice * result.added)}`,
      },
    );
  };

  const unitOptions = units.map((unit) => {
    const inCartU = cartLineQuantity(cart.lines, product.id, unit.type);
    const previewQty = inCartU + qty;
    const { current, list } = unitSellingAndListPrice(unit, previewQty);
    return {
      type: unit.type,
      label: unit.label,
      currentPriceLabel: formatProductVnd(current),
      listPriceLabel: list != null ? formatProductVnd(list) : null,
      hasPromo: hasUnitWholesalePromo(unit),
    };
  });

  return (
    <>
      <Link href={backHref}>
        <Button variant="outline" className="rounded-xl">
          <ArrowLeft className="mr-2 size-4" /> Quay lại danh mục
        </Button>
      </Link>

      <div className="space-y-8">
      <ProductDetailLayout
        gallery={
          <ProductDetailGallery images={displayImages} alt={product.name} />
        }
        details={
          <>
            <ProductDetailInfoHeader
              categoryLabel={categoryLabel}
              title={product.name}
              description={product.description}
              couponBadges={product.coupons ?? []}
            />

            <ProductDetailPurchaseCard>
              {units.length > 1 ? (
                <ProductDetailPurchaseCardSection>
                  <ProductDetailUnitPicker
                    options={unitOptions}
                    selectedType={selectedUnit.type}
                    onSelect={handleUnitChange}
                    showPrice={false}
                    compact
                    showLabel={false}
                  />
                </ProductDetailPurchaseCardSection>
              ) : null}

              <ProductDetailPurchaseCardSection variant="order">
                <ProductDetailOrderRow
                  unitPrice={unitPrice}
                  listPrice={listPrice}
                  unitLabel={selectedUnit.label}
                  hasWholesale={isWholesale}
                  qty={qty}
                  unitType={selectedUnit.type}
                  onQtyChange={(next) => setQty(clampQty(next))}
                  minQty={minPurchaseQty}
                  maxQty={maxQty}
                  equivalentTotal={totalUnits}
                  equivalentUnit={product.unit}
                  stockCount={unitStockCount}
                  stockStatus={
                    outOfStock ? "out" : stockWarning ? "low" : "ok"
                  }
                  footer={
                    <p className="text-[11px] text-muted-foreground">
                      {qtyInCart > 0 ? (
                        <>
                          Trong giỏ{" "}
                          <span className="font-semibold text-foreground">
                            {qtyInCart}
                          </span>
                          {" / tồn "}
                          <span className="font-semibold text-foreground">
                            {unitStockCount}
                          </span>
                          {" · còn thêm "}
                          <span className="font-semibold text-primary">
                            {availableQty}
                          </span>
                          {" + đặt "}
                          <span className="font-semibold text-foreground">
                            {qty}
                          </span>
                          {" → áp giá "}
                          <span className="font-semibold text-primary">
                            {pricingQty}
                          </span>
                        </>
                      ) : (
                        <>
                          Tối đa{" "}
                          <span className="font-semibold text-foreground">
                            {availableQty}
                          </span>{" "}
                          {selectedUnit.type} (pool{" "}
                          <span className="font-semibold text-foreground tabular-nums">
                            {baseStock}
                          </span>{" "}
                          {product.unit})
                        </>
                      )}
                    </p>
                  }
                />
              </ProductDetailPurchaseCardSection>

              {showPromoGiftsSection ? (
                <ProductDetailPurchaseCardSection variant="muted">
                  <ProductDetailPromoGiftsSection
                    unit={selectedUnit}
                    giftRules={giftRules}
                    pricingQty={pricingQty}
                    productSellQty={productSellQty}
                    giftHrefForRule={giftHrefForRule}
                  />
                </ProductDetailPurchaseCardSection>
              ) : null}
            </ProductDetailPurchaseCard>

            {(stockWarning || outOfStock) ? (
              <ProductDetailCallout
                tone="warning"
                icon={AlertTriangle}
                title={
                  outOfStock
                    ? qtyInCart > 0
                      ? "Đã đạt tồn kho trong giỏ"
                      : "Hết hàng"
                    : "Sắp hết hàng"
                }
              />
            ) : null}

            <ProductDetailMetaGrid
              compact
              items={[
                { label: "Thương hiệu", value: product.brand ?? "—" },
                { label: "Xuất xứ", value: product.origin ?? "—" },
                { label: "SKU", value: product.sku },
              ]}
            />

            <ProductDetailActions
              primary={
                <Button
                  className="h-11 w-full rounded-xl px-6 text-sm font-black shadow-sm"
                  onClick={handleAddToCart}
                  disabled={outOfStock}
                >
                  <ShoppingCart className="mr-2 size-4" />
                  {outOfStock
                    ? "Hết hàng"
                    : `Thêm vào giỏ – ${formatProductVnd(totalPrice)}`}
                </Button>
              }
              secondary={
                <Link href={supportHref} className="block h-full">
                  <Button
                    variant="outline"
                    className="h-11 w-full rounded-xl px-5 text-sm font-semibold sm:min-w-[7.5rem]"
                  >
                    <Truck className="mr-1.5 size-3.5" /> Tư vấn
                  </Button>
                </Link>
              }
              trust={
                !outOfStock ? (
                  <p className="flex items-center gap-1.5 text-xs font-medium text-success">
                    <CheckCircle2 className="size-3.5 shrink-0" />
                    Còn hàng · Giao hôm nay hoặc ngày mai
                  </p>
                ) : null
              }
            />
          </>
        }
      />

      <ProductSuggestions productId={product.id} category={product.category} />
      </div>
    </>
  );
}

src/components/shared/product-suggestion.content:
"use client";

import Link from "next/link";
import { ArrowRight, Package2, Sparkles, Tag } from "lucide-react";
import { ProductDiscountBadge } from "@ui/components/product";
import { Badge } from "@ui/components/badge";
import { formatProductVnd, hasUnitWholesalePromo } from "@ui/components/product";
import type { Product } from "@/lib/api";
import { getProductUnits } from "@/lib/catalog-filters";
import { unitSellingAndListPrice } from "@workspace/api-client";
import { useSuggestedProducts } from "@/hooks/queries";

type ProductSuggestionsProps = {
  productId: number;
  category: string;
};

function formatCategoryLabel(category: string) {
  return (
    category.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) ||
    category
  );
}

function SuggestionCard({ product }: { product: Product }) {
  const units = getProductUnits(product);
  const unit = units[0];
  const { current, list } = unit
    ? unitSellingAndListPrice(unit, 1)
    : { current: product.retailPrice, list: null as number | null };
  const image = product.images?.[0];
  const categoryLabel = formatCategoryLabel(product.category);
  const meta = [product.brand, product.origin].filter(Boolean).join(" · ");
  const firstCoupon = product.coupons?.[0];
  const hasPromo = unit ? hasUnitWholesalePromo(unit) : false;
  const discountPercent =
    list != null && list > current
      ? Math.round(((list - current) / list) * 100)
      : 0;

  return (
    <Link
      href={`/catalog/${product.id}`}
      className="group/card flex h-full min-w-[10.5rem] shrink-0 snap-start flex-col overflow-hidden rounded-3xl border border-outline-variant/35 bg-background shadow-sm transition-all duration-300 hover:-translate-y-0.5 hover:border-primary/25 hover:shadow-lg sm:min-w-[12.5rem] lg:min-w-0"
    >
      <div className="relative aspect-square overflow-hidden bg-gradient-to-b from-white to-muted/25">
        {image ? (
          <img
            src={image}
            alt={product.name}
            className="size-full object-cover transition-transform duration-500 group-hover/card:scale-[1.04]"
          />
        ) : (
          <div className="flex size-full items-center justify-center">
            <Package2 className="size-10 text-outline-variant" aria-hidden />
          </div>
        )}

        <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/35 via-transparent to-transparent opacity-0 transition-opacity duration-300 group-hover/card:opacity-100" />

        {firstCoupon ? (
          <Badge
            variant="coupon"
            size="xs"
            shape="pill"
            className="absolute top-2.5 left-2.5 max-w-[72%] truncate shadow-sm"
          >
            <Tag aria-hidden />
            {firstCoupon}
          </Badge>
        ) : null}

        {hasPromo && discountPercent > 0 ? (
          <ProductDiscountBadge
            percent={discountPercent}
            className="absolute top-2.5 right-2.5 shadow-sm"
          />
        ) : (
          <Badge
            variant="overlay"
            size="xs"
            className="absolute top-2.5 right-2.5 max-w-[70%] truncate"
          >
            {categoryLabel}
          </Badge>
        )}

        <span className="absolute inset-x-0 bottom-3 flex justify-center opacity-0 transition-all duration-300 group-hover/card:translate-y-0 group-hover/card:opacity-100 translate-y-1">
          <span className="inline-flex items-center gap-1 rounded-full bg-background/95 px-3 py-1 text-xs font-bold text-foreground shadow-md backdrop-blur-sm">
            Xem chi tiết
            <ArrowRight className="size-3.5" aria-hidden />
          </span>
        </span>
      </div>

      <div className="flex flex-1 flex-col gap-2.5 p-4">
        <p className="text-[11px] font-bold uppercase tracking-widest text-primary/75">
          {categoryLabel}
        </p>

        <p className="line-clamp-2 min-h-[2.5rem] text-sm font-bold leading-snug text-foreground transition-colors group-hover/card:text-primary sm:text-base">
          {product.name}
        </p>

        {meta ? (
          <p className="line-clamp-1 text-xs font-medium text-muted-foreground">
            {meta}
          </p>
        ) : null}

        <div className="mt-auto space-y-1 border-t border-outline-variant/25 pt-3">
          <div className="flex flex-wrap items-baseline gap-2">
            {list != null ? (
              <span className="text-xs font-semibold text-muted-foreground line-through sm:text-sm">
                {formatProductVnd(list)}
              </span>
            ) : null}
            <span className="text-lg font-black text-primary sm:text-xl">
              {formatProductVnd(current)}
            </span>
          </div>
          {unit ? (
            <p className="text-[11px] font-medium text-muted-foreground">
              / {unit.label}
              {hasPromo ? (
                <span className="ml-1 font-semibold text-primary">· Có KM</span>
              ) : null}
            </p>
          ) : null}
        </div>
      </div>
    </Link>
  );
}

function SuggestionsSkeleton() {
  return (
    <div className="-mx-1 flex gap-3 overflow-hidden px-1 pb-1 sm:gap-4 lg:mx-0 lg:grid lg:grid-cols-4 lg:overflow-visible lg:px-0">
      {Array.from({ length: 4 }).map((_, index) => (
        <div
          key={index}
          className="min-w-[10.5rem] shrink-0 overflow-hidden rounded-3xl border border-outline-variant/30 sm:min-w-[12.5rem] lg:min-w-0"
        >
          <div className="aspect-square animate-pulse bg-muted/40" />
          <div className="space-y-2.5 p-4">
            <div className="h-3 w-16 animate-pulse rounded bg-muted/40" />
            <div className="h-4 animate-pulse rounded bg-muted/40" />
            <div className="h-4 w-[80%] animate-pulse rounded bg-muted/40" />
            <div className="h-6 w-24 animate-pulse rounded bg-muted/40" />
          </div>
        </div>
      ))}
    </div>
  );
}

export function ProductSuggestions({
  productId,
  category,
}: ProductSuggestionsProps) {
  const { data, isLoading } = useSuggestedProducts(productId, category);
  const categoryLabel = formatCategoryLabel(category);
  const catalogHref =
    category.trim().length > 0
      ? `/catalog?cat=${encodeURIComponent(category.trim())}`
      : "/catalog";

  if (!isLoading && (!data || data.length === 0)) return null;

  return (
    <section
      className="overflow-hidden rounded-2xl border border-outline-variant/30 bg-card shadow-md ring-1 ring-black/[0.03] dark:ring-white/[0.04]"
      aria-labelledby="product-suggestions-heading"
    >
      <div className="border-b border-outline-variant/25 bg-gradient-to-r from-primary/[0.06] via-background to-muted/20 px-4 py-4 sm:px-6 sm:py-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="space-y-1">
            <p className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-widest text-primary">
              <Sparkles className="size-3.5 shrink-0" aria-hidden />
              Mua kèm
            </p>
            <h2
              id="product-suggestions-heading"
              className="text-lg font-black text-foreground sm:text-xl"
            >
              Sản phẩm gợi ý
            </h2>
            <p className="text-sm text-muted-foreground">
              Cùng nhóm {categoryLabel} và các mặt hàng hay đặt chung
            </p>
          </div>

          <Link
            href={catalogHref}
            className="inline-flex items-center gap-1 rounded-xl border border-primary/20 bg-primary/5 px-3 py-2 text-sm font-bold text-primary transition-colors hover:bg-primary/10"
          >
            Xem danh mục
            <ArrowRight className="size-4" aria-hidden />
          </Link>
        </div>
      </div>

      <div className="p-4 sm:p-6">
        {isLoading ? (
          <SuggestionsSkeleton />
        ) : (
          <div className="-mx-1 flex gap-3 overflow-x-auto px-1 pb-1 [-ms-overflow-style:none] [scrollbar-width:none] sm:gap-4 lg:mx-0 lg:grid lg:grid-cols-4 lg:overflow-visible lg:px-0 [&::-webkit-scrollbar]:hidden">
            {data!.map((item) => (
              <SuggestionCard key={item.id} product={item} />
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

